import pandas as pd


def run(inputs: dict) -> dict:
    dim_price = inputs["dim_price"].copy()
    stg_price = inputs["stg_price"].copy()
    batch_control = inputs["batch_control"].copy()

    batch_date = pd.to_datetime(batch_control["batch_date"].iloc[0])

    # Build per-product list of existing version dicts
    products_rows = {}

    for _, r in dim_price.iterrows():
        pid = r["product_id"]
        row = {
            "product_id": pid,
            "list_price": r["list_price"],
            "eff_start_date": pd.to_datetime(r["eff_start_date"]),
            "eff_end_date": (
                pd.NaT if pd.isna(r["eff_end_date"]) else pd.to_datetime(r["eff_end_date"])
            ),
        }
        products_rows.setdefault(pid, []).append(row)

    # Determine all product ids (existing + staged)
    all_pids = set(products_rows.keys()) | set(stg_price["product_id"].unique())

    # Ensure every product id has an entry (possibly empty list)
    for pid in all_pids:
        products_rows.setdefault(pid, [])

    # Sort staged rows per product by effective_date ascending
    stg_sorted = stg_price.sort_values(["product_id", "effective_date"], kind="mergesort")

    for pid in all_pids:
        rows = products_rows[pid]

        # find current tail: version with latest eff_start_date
        tail = None
        if rows:
            tail = max(rows, key=lambda r: r["eff_start_date"])

        staged_rows = stg_sorted[stg_sorted["product_id"] == pid]

        for _, s in staged_rows.iterrows():
            s_price = s["list_price"]
            s_date = pd.to_datetime(s["effective_date"])

            if tail is not None and tail["list_price"] == s_price:
                # unchanged, skip
                continue
            else:
                if tail is not None:
                    tail["eff_end_date"] = s_date
                new_row = {
                    "product_id": pid,
                    "list_price": s_price,
                    "eff_start_date": s_date,
                    "eff_end_date": pd.NaT,
                }
                rows.append(new_row)
                tail = new_row

        products_rows[pid] = rows

    # Flatten all rows
    out_rows = []
    for pid, rows in products_rows.items():
        for r in rows:
            start = r["eff_start_date"]
            end = r["eff_end_date"]
            if pd.isna(end):
                is_current = 1 if start <= batch_date else 0
            else:
                is_current = 1 if (start <= batch_date) and (end > batch_date) else 0
            out_rows.append(
                {
                    "product_id": r["product_id"],
                    "list_price": r["list_price"],
                    "eff_start_date": start,
                    "eff_end_date": end,
                    "is_current": is_current,
                }
            )

    out_df = pd.DataFrame(
        out_rows,
        columns=["product_id", "list_price", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out_df.empty:
        out_df["product_id"] = out_df["product_id"].astype("int64")
        out_df["list_price"] = out_df["list_price"].astype("float64")
        out_df["eff_start_date"] = pd.to_datetime(out_df["eff_start_date"])
        out_df["eff_end_date"] = pd.to_datetime(out_df["eff_end_date"])
        out_df["is_current"] = out_df["is_current"].astype("int64")
    else:
        out_df = pd.DataFrame(
            {
                "product_id": pd.Series(dtype="int64"),
                "list_price": pd.Series(dtype="float64"),
                "eff_start_date": pd.Series(dtype="datetime64[us]"),
                "eff_end_date": pd.Series(dtype="datetime64[us]"),
                "is_current": pd.Series(dtype="int64"),
            }
        )

    out_df = out_df.sort_values(
        ["product_id", "eff_start_date"], kind="mergesort"
    ).reset_index(drop=True)

    return {"dim_price_out": out_df}
